The following example illustrate how to implement this:

public void MyMethod()
{
  try
  {
    DoSomething();
    DoSomethingElse();
  }
  catch( SomeSpecificException e )
  {
    HandleTheException();
  }
  catch( Exception e )
  {
    if( ExceptionFilter.IsPublicException( e ) )
      throw; // Simply pass the exception as-is to the caller

    throw new MyUnexpectedException( "Something unexpected happened.", e );
  }
}

The following example demonstrates how to create a spanned zip file.

QuickZip.Zip("a:\test.zip", String.Empty, True, True, False, New QuickZip.DiskRequiredCallback(AddressOf Me.QuickDiskRequired), Nothing, "d:\file.txt")

' This method will handle the DiskRequired events that are raised when creating
' spanned or split zip files.
Private Function QuickDiskRequired(ByVal zipFile As String, ByVal diskNumber As Integer, ByVal userData As Object) As Boolean
     If (MessageBox.Show("Disk #" + diskNumber.ToString() + " is required.", "Disk Required", MessageBoxButtons.OKCancel) = DialogResult.OK) Then
          Return True
     Else
          Return False
     End If
End Function


QuickZip.Zip( @"a:\test.zip", string.Empty, true, true, false, new QuickZip.DiskRequiredCallback( this.QuickDiskRequired ), null, @"d:\file.txt" );

// This method will handle the DiskRequired events that are raised when creating
// spanned or split zip files.
private bool QuickDiskRequired( string zipFile, int diskNumber, object userData )
{
     if( MessageBox.Show( "Disk #" + diskNumber.ToString() + " is required.", "Disk Required", MessageBoxButtons.OKCancel ) == DialogResult.OK )
          return true;
     else
          return false;    
}

The following example demonstrates how to create a spanned self-extracting zip file.

Dim sfx As New XceedSfxPrefix(New DiskFile("C:\Program Files\Xceed Components\Xceed Zip for .NET\Sfx\xcdsfx32.bin"))

sfx.DialogStrings(DialogStrings.Title) = "Welcome to Xceed Zip for .NET!"
sfx.DefaultDestinationFolder = "C:\"
sfx.ExistingFileBehavior = ExistingFileBehavior.OverwriteOlderOnly

QuickZip.Zip("a:\sfx.exe", String.Empty, True, True, False, sfx, New QuickZip.DiskRequiredCallback(AddressOf Me.QuickDiskRequired), Nothing, "d:\file.txt")

